UPDATE hyperlink_task_runtime SET
  first_visit_at=CASE WHEN #{firstVisit} THEN #{now} ELSE first_visit_at END,
  last_visit_at=#{now},
  click_uv_num=click_uv_num+CASE WHEN #{firstVisit} THEN 1 ELSE 0 END,
  click_total=click_total+1, updated_at=#{now}
WHERE hyperlink_task_id=#{taskId}
